import json, glob, os
man=None
try:
    man=json.load(open('inputs/manifest.json'))
except Exception as e:
    print('manifest err', e)
print(json.dumps(man)[:1500] if man else '')
paths = sorted(set(glob.glob('inputs/**/*.xlsx', recursive=True)+glob.glob('**/*.xlsx', recursive=True)+glob.glob('inputs/**/*', recursive=True)))
print(paths[:15])
import openpyxl
xl=[p for p in paths if p.lower().endswith('.xlsx')]
if not xl:
    print('no xlsx found')
else:
    p=xl[0]
    print('file', p, os.path.getsize(p))
    wb=openpyxl.load_workbook(p, data_only=False)
    print('sheets', wb.sheetnames)
    try:
        print('ext_links', [(el.file_link.Target if el.file_link else None) for el in wb._external_links])
    except Exception as e:
        print('ext err', e)
    for ws in wb.worksheets:
        print('=== sheet', ws.title, ws.max_row, ws.max_column)
        for r in ws.iter_rows(min_row=1, max_row=min(ws.max_row,14), max_col=min(ws.max_column,4)):
            print(ws.title, [(c.coordinate, c.data_type, c.value) for c in r])
    wb2=openpyxl.load_workbook(p, data_only=True)
    for name in wb2.sheetnames:
        ws=wb2[name]
        print('cached', name, [[(c.coordinate, c.value) for c in r] for r in ws.iter_rows(min_row=1, max_row=min(ws.max_row,4), max_col=min(ws.max_column,3))])

import openpyxl
wb = openpyxl.load_workbook('inputs/delivery.xlsx', data_only=False)
for ws in wb.worksheets:
    print('SHEET', ws.title, ws.max_row, ws.max_column)
    for r in range(1, min(ws.max_row, 14)+1):
        vals=[]
        for c in range(1, min(ws.max_column,2)+1):
            v=ws.cell(r,c).value
            vals.append((ws.cell(r,c).coordinate, repr(v), type(v).__name__))
        print(vals)
